{
  "iteration": 1,
  "pcvs": [
    {
      "name": "lookup_enabled",
      "expression": "int(self.enable_caching and not request.skip_reading_prefix_cache)",
      "rationale": "Separates the early return from prefix-cache lookup."
    },
    {
      "name": "has_lookup_blocks",
      "expression": "int(self.enable_caching and not request.skip_reading_prefix_cache and min(len(request.block_hashes), (request.num_tokens - 1) // self.kv_cache_config.kv_cache_groups[0].kv_cache_spec.block_size) > 0)",
      "rationale": "Distinguishes empty searches from searches requiring at least one hash lookup."
    },
    {
      "name": "first_block_cached",
      "expression": "int(self.enable_caching and not request.skip_reading_prefix_cache and bool(request.block_hashes) and self.block_pool.get_cached_block(request.block_hashes[0], [0]) is not None)",
      "rationale": "A single bounded cache lookup distinguishes immediate misses from reusable prefixes."
    },
    {
      "name": "cached_prefix_search_extent",
      "expression": "min(len(request.block_hashes), (request.num_tokens - 1) // self.kv_cache_config.kv_cache_groups[0].kv_cache_spec.block_size) if self.enable_caching and not request.skip_reading_prefix_cache and request.block_hashes and self.block_pool.get_cached_block(request.block_hashes[0], [0]) is not None else 0",
      "rationale": "Estimates traversal and result-building work for the workload's shared prefixes, respecting the final-token recomputation limit."
    }
  ],
  "hypothesis": "For this single-group full-attention workload, instruction count is driven by fixed lookup overhead, whether the first block misses, and the searchable prefix length when the first block hits."
}
